import torch
import torch.nn as nn
import torch.nn.functional as F


class SE(nn.Module):
    def __init__(self, c, r=4):
        super().__init__()
        h = max(c // r, 4)
        self.fc1 = nn.Linear(c, h)
        self.fc2 = nn.Linear(h, c)

    def forward(self, x):
        s = torch.sigmoid(self.fc2(F.silu(self.fc1(x.mean(-1)))))
        return x * s.unsqueeze(-1)


class DBlock(nn.Module):
    def __init__(self, cin, cout, ks=7, dil=1, expand=2, drop=0.05):
        super().__init__()
        mid = cin * expand
        self.pw1 = nn.Sequential(nn.Conv1d(cin, mid, 1, bias=False), nn.BatchNorm1d(mid), nn.SiLU())
        self.dw = nn.Sequential(
            nn.Conv1d(mid, mid, ks, padding=dil * (ks // 2), dilation=dil, groups=mid, bias=False),
            nn.BatchNorm1d(mid), nn.SiLU(),
        )
        self.se = SE(mid)
        self.pw2 = nn.Sequential(nn.Conv1d(mid, cout, 1, bias=False), nn.BatchNorm1d(cout))
        self.drop = nn.Dropout(drop)
        self.skip = nn.Conv1d(cin, cout, 1, bias=False) if cin != cout else nn.Identity()

    def forward(self, x):
        h = self.pw2(self.se(self.dw(self.pw1(x))))
        return self.skip(x) + self.drop(h)


class AttnPool(nn.Module):
    def __init__(self, c, heads=4):
        super().__init__()
        self.score = nn.Conv1d(c, heads, 1)
        self.heads = heads

    def forward(self, x):
        w = torch.softmax(self.score(x), dim=-1)          # B,H,L
        p = torch.einsum('bhl,bcl->bhc', w, x)            # B,H,C
        return p.flatten(1)


class Net(nn.Module):
    def __init__(self):
        super().__init__()
        self.stem_convs = nn.ModuleList([
            nn.Conv1d(4, 32, 5, padding=2, bias=False),
            nn.Conv1d(4, 32, 11, padding=5, bias=False),
            nn.Conv1d(4, 32, 19, padding=9, bias=False),
        ])
        self.stem_bn = nn.Sequential(nn.BatchNorm1d(96), nn.SiLU())
        self.early = nn.Sequential(
            DBlock(96, 96, 7, 1), DBlock(96, 96, 9, 1), DBlock(96, 96, 7, 1),
        )
        self.pool = nn.MaxPool1d(2)
        dils = [1, 2, 4, 8, 1]
        blocks, c = [], 96
        for i, d in enumerate(dils):
            blocks.append(DBlock(c, 128, 7 if i % 2 == 0 else 9, d))
            c = 128
        self.late = nn.Sequential(*blocks)
        self.attn = AttnPool(128, 4)
        self.head = nn.Sequential(
            nn.Dropout(0.3), nn.Linear(128 * 4 + 128 * 2, 128), nn.SiLU(),
            nn.Dropout(0.1), nn.Linear(128, 1),
        )

    def forward(self, x):
        h = torch.cat([m(x) for m in self.stem_convs], dim=1)
        h = self.stem_bn(h)
        h = self.early(h)
        h = self.pool(h)
        h = self.late(h)
        z = torch.cat([self.attn(h), h.mean(-1), h.amax(-1)], dim=1)
        return self.head(z).squeeze(-1)

import torch
import torch.nn as nn
import torch.nn.functional as F


class SE(nn.Module):
    def __init__(self, c, r=4):
        super().__init__()
        h = max(c // r, 4)
        self.fc1 = nn.Linear(c, h)
        self.fc2 = nn.Linear(h, c)

    def forward(self, x):
        s = torch.sigmoid(self.fc2(F.silu(self.fc1(x.mean(-1)))))
        return x * s.unsqueeze(-1)


class GLUBlock(nn.Module):
    def __init__(self, c, ks=9, expand=2):
        super().__init__()
        mid = c * expand
        self.dw = nn.Conv1d(c, c, ks, padding=ks // 2, groups=c, bias=False)
        self.bn = nn.BatchNorm1d(c)
        self.pw1 = nn.Conv1d(c, mid * 2, 1)
        self.se = SE(mid)
        self.pw2 = nn.Conv1d(mid, c, 1, bias=False)
        self.bn2 = nn.BatchNorm1d(c)
        self.gamma = nn.Parameter(torch.full((1, c, 1), 0.5))

    def forward(self, x):
        h = self.bn(self.dw(x))
        h = F.glu(self.pw1(h), dim=1)
        h = self.se(h)
        h = self.bn2(self.pw2(h))
        return x + self.gamma * h


class Transition(nn.Module):
    def __init__(self, cin, cout):
        super().__init__()
        self.conv = nn.Conv1d(cin, cout, 1, bias=False)
        self.bn = nn.BatchNorm1d(cout)
        self.pool = nn.MaxPool1d(2)

    def forward(self, x):
        return self.pool(F.silu(self.bn(self.conv(x))))


class MultiQueryPool(nn.Module):
    def __init__(self, c, q=4):
        super().__init__()
        self.score = nn.Conv1d(c, q, 1)
        self.q = q

    def forward(self, x):
        a = torch.softmax(self.score(x), dim=-1)          # B,Q,L
        p = torch.einsum('bql,bcl->bqc', a, x)            # B,Q,C
        return p.flatten(1)


class Net(nn.Module):
    def __init__(self):
        super().__init__()
        self.stem = nn.Sequential(
            nn.Conv1d(4, 64, 9, padding=4, bias=False), nn.BatchNorm1d(64), nn.SiLU())
        cfg = [(64, 2), (96, 2), (128, 3), (160, 2)]
        layers, c = [], 64
        for i, (w, n) in enumerate(cfg):
            if w != c:
                layers.append(nn.Conv1d(c, w, 1, bias=False))
                layers.append(nn.BatchNorm1d(w))
                c = w
            for j in range(n):
                layers.append(GLUBlock(c, ks=9 if j % 2 == 0 else 7))
            if i < len(cfg) - 1:
                layers.append(nn.MaxPool1d(2))
        self.tower = nn.Sequential(*layers)
        self.pool = MultiQueryPool(c, 4)
        self.head = nn.Sequential(
            nn.Dropout(0.3), nn.Linear(c * 5, 96), nn.SiLU(),
            nn.Dropout(0.1), nn.Linear(96, 1))

    def forward(self, x):
        h = self.tower(self.stem(x))
        z = torch.cat([self.pool(h), h.amax(-1)], dim=1)
        return self.head(z).squeeze(-1)

import torch
import torch.nn as nn
import torch.nn.functional as F


class SE(nn.Module):
    def __init__(self, c, r=4):
        super().__init__()
        h = max(c // r, 4)
        self.fc1 = nn.Linear(c, h)
        self.fc2 = nn.Linear(h, c)

    def forward(self, x):
        s = torch.sigmoid(self.fc2(F.silu(self.fc1(x.mean(-1)))))
        return x * s.unsqueeze(-1)


class MultiStem(nn.Module):
    def __init__(self, c=96):
        super().__init__()
        ks = (3, 5, 9, 15, 21)
        outs = (24, 24, 20, 16, 12)
        assert sum(outs) == c
        self.convs = nn.ModuleList([nn.Conv1d(4, o, k, padding=k // 2, bias=False) for k, o in zip(ks, outs)])
        self.bn = nn.BatchNorm1d(c)
        self.mix = nn.Sequential(nn.Conv1d(c, c, 1, bias=False), nn.BatchNorm1d(c), nn.SiLU())

    def forward(self, x):
        h = torch.cat([m(x) for m in self.convs], dim=1)
        return self.mix(F.silu(self.bn(h)))


class GatedDilBlock(nn.Module):
    def __init__(self, c, expand=2, ks=5, dil=1):
        super().__init__()
        mid = c * expand
        self.pw = nn.Conv1d(c, 2 * mid, 1, bias=False)
        self.dw = nn.Conv1d(mid, mid, ks, padding=dil * (ks // 2), dilation=dil, groups=mid, bias=False)
        self.bn1 = nn.BatchNorm1d(mid)
        self.se = SE(mid)
        self.proj = nn.Conv1d(mid, c, 1, bias=False)
        self.bn2 = nn.BatchNorm1d(c)
        self.gamma = nn.Parameter(torch.tensor(0.5))

    def forward(self, x):
        a, g = self.pw(x).chunk(2, dim=1)
        h = a * torch.sigmoid(g)
        h = F.silu(self.bn1(self.dw(h)))
        h = self.bn2(self.proj(self.se(h)))
        return x + self.gamma * h


class AttnPool(nn.Module):
    def __init__(self, c, heads=4):
        super().__init__()
        self.score = nn.Conv1d(c, heads, 1)

    def forward(self, x):
        w = torch.softmax(self.score(x), dim=-1)          # B,H,L
        p = torch.einsum('bhl,bcl->bhc', w, x)            # B,H,C
        return p.flatten(1)


class Net(nn.Module):
    def __init__(self):
        super().__init__()
        c = 96
        self.stem = MultiStem(c)
        dils = [1, 2, 4, 8, 1, 2, 4, 8]
        self.tower = nn.Sequential(*[GatedDilBlock(c, 2, 5 if i % 2 == 0 else 7, d) for i, d in enumerate(dils)])
        self.pool = AttnPool(c, 4)
        self.head = nn.Sequential(
            nn.Dropout(0.3), nn.Linear(c * 4 + c * 2, 128), nn.SiLU(), nn.Dropout(0.1), nn.Linear(128, 1)
        )

    def forward(self, x):
        h = self.tower(self.stem(x))
        z = torch.cat([self.pool(h), h.mean(-1), h.amax(-1)], dim=1)
        return self.head(z).squeeze(-1)

import torch
import torch.nn as nn
import torch.nn.functional as F


class SE(nn.Module):
    def __init__(self, c, r=4):
        super().__init__()
        h = max(c // r, 4)
        self.fc1 = nn.Linear(c, h)
        self.fc2 = nn.Linear(h, c)

    def forward(self, x):
        s = torch.sigmoid(self.fc2(F.silu(self.fc1(x.mean(-1)))))
        return x * s.unsqueeze(-1)


class EffBlock(nn.Module):
    def __init__(self, cin, cout, ks=7, expand=2, dil=1, drop=0.05):
        super().__init__()
        mid = cin * expand
        self.body = nn.Sequential(
            nn.Conv1d(cin, mid, 1, bias=False), nn.BatchNorm1d(mid), nn.SiLU(),
            nn.Conv1d(mid, mid, ks, padding=dil * (ks // 2), dilation=dil, groups=mid, bias=False),
            nn.BatchNorm1d(mid), nn.SiLU(),
        )
        self.se = SE(mid)
        self.proj = nn.Sequential(nn.Conv1d(mid, cout, 1, bias=False), nn.BatchNorm1d(cout))
        self.drop = nn.Dropout(drop)
        self.skip = nn.Conv1d(cin, cout, 1, bias=False) if cin != cout else nn.Identity()

    def forward(self, x):
        return self.skip(x) + self.drop(self.proj(self.se(self.body(x))))


class UpFuse(nn.Module):
    def __init__(self, cin, cskip, cout):
        super().__init__()
        self.up = nn.Upsample(scale_factor=2, mode='nearest')
        self.fuse = nn.Sequential(nn.Conv1d(cin + cskip, cout, 1, bias=False), nn.BatchNorm1d(cout), nn.SiLU())
        self.blk = EffBlock(cout, cout, ks=7)

    def forward(self, x, skip):
        return self.blk(self.fuse(torch.cat([self.up(x), skip], dim=1)))


class Net(nn.Module):
    def __init__(self):
        super().__init__()
        self.stem = nn.Sequential(nn.Conv1d(4, 64, 9, padding=4, bias=False), nn.BatchNorm1d(64), nn.SiLU())
        self.e1 = nn.Sequential(EffBlock(64, 64, ks=9), EffBlock(64, 64, ks=7))             # 200
        self.e2 = nn.Sequential(EffBlock(64, 96, ks=9), EffBlock(96, 96, ks=7))             # 100
        self.e3 = nn.Sequential(EffBlock(96, 128, ks=9), EffBlock(128, 128, ks=7))          # 50
        self.pool = nn.MaxPool1d(2)
        self.bott = nn.Sequential(                                                           # 25
            EffBlock(128, 160, ks=7, dil=1), EffBlock(160, 160, ks=7, dil=2),
            EffBlock(160, 160, ks=7, dil=4), EffBlock(160, 128, ks=7, dil=1),
        )
        self.d3 = UpFuse(128, 128, 128)  # 50
        self.d2 = UpFuse(128, 96, 96)    # 100
        self.head = nn.Sequential(
            nn.Dropout(0.3), nn.Linear(96 * 2 + 128 * 2 + 128 * 2, 96), nn.SiLU(), nn.Dropout(0.1), nn.Linear(96, 1)
        )

    def forward(self, x):
        h1 = self.e1(self.stem(x))
        h2 = self.e2(self.pool(h1))
        h3 = self.e3(self.pool(h2))
        b = self.bott(self.pool(h3))
        u3 = self.d3(b, h3)
        u2 = self.d2(u3, h2)
        z = torch.cat([
            u2.mean(-1), u2.amax(-1),
            u3.mean(-1), u3.amax(-1),
            b.mean(-1), b.amax(-1),
        ], dim=1)
        return self.head(z).squeeze(-1)

import torch
import torch.nn as nn
import torch.nn.functional as F


class SE(nn.Module):
    def __init__(self, c, r=4):
        super().__init__()
        h = max(c // r, 4)
        self.fc1 = nn.Linear(c, h)
        self.fc2 = nn.Linear(h, c)

    def forward(self, x):
        s = torch.sigmoid(self.fc2(F.silu(self.fc1(x.mean(-1)))))
        return x * s.unsqueeze(-1)


class EffBlock(nn.Module):
    def __init__(self, cin, cout, ks=7, expand=2):
        super().__init__()
        mid = cin * expand
        self.body = nn.Sequential(
            nn.Conv1d(cin, mid, 1, bias=False), nn.BatchNorm1d(mid), nn.SiLU(),
            nn.Conv1d(mid, mid, ks, padding=ks // 2, groups=mid, bias=False), nn.BatchNorm1d(mid), nn.SiLU(),
        )
        self.se = SE(mid)
        self.proj = nn.Sequential(nn.Conv1d(mid, cout, 1, bias=False), nn.BatchNorm1d(cout))
        self.skip = nn.Conv1d(cin, cout, 1, bias=False) if cin != cout else nn.Identity()

    def forward(self, x):
        return self.skip(x) + self.proj(self.se(self.body(x)))


class AttnLayer(nn.Module):
    def __init__(self, d, L, heads=4, drop=0.1):
        super().__init__()
        self.pos = nn.Parameter(torch.randn(1, L, d) * 0.02)
        self.n1 = nn.LayerNorm(d)
        self.attn = nn.MultiheadAttention(d, heads, dropout=drop, batch_first=True)
        self.n2 = nn.LayerNorm(d)
        self.ff = nn.Sequential(nn.Linear(d, d * 2), nn.GELU(), nn.Dropout(drop), nn.Linear(d * 2, d))

    def forward(self, x):  # x: (B, C, L)
        t = x.transpose(1, 2) + self.pos
        h = self.n1(t)
        t = t + self.attn(h, h, h, need_weights=False)[0]
        t = t + self.ff(self.n2(t))
        return t.transpose(1, 2)


class Net(nn.Module):
    def __init__(self):
        super().__init__()
        self.stems = nn.ModuleList([nn.Conv1d(4, 32, k, padding=k // 2, bias=False) for k in (5, 9, 15)])
        self.stem_bn = nn.Sequential(nn.BatchNorm1d(96), nn.SiLU())
        cfg = [(96, 128, 7), (128, 128, 9), "P", (128, 160, 7), (160, 160, 9), "P", (160, 160, 7), (160, 160, 9), "P"]
        layers, c = [], 96
        for item in cfg:
            if item == "P":
                layers.append(nn.MaxPool1d(2))
            else:
                layers.append(EffBlock(c, item[1], ks=item[2]))
                c = item[1]
        self.tower = nn.Sequential(*layers)  # 200 -> 25
        self.attn = AttnLayer(c, 25)
        self.post = EffBlock(c, c, ks=5)
        self.head = nn.Sequential(nn.Dropout(0.3), nn.Linear(c * 2, 64), nn.SiLU(), nn.Dropout(0.1), nn.Linear(64, 1))

    def forward(self, x):
        h = torch.cat([s(x) for s in self.stems], dim=1)
        h = self.stem_bn(h)
        h = self.tower(h)
        h = self.post(self.attn(h))
        h = torch.cat([h.mean(-1), h.amax(-1)], dim=1)
        return self.head(h).squeeze(-1)

