class EffBlock(nn.Module):
    def __init__(self, cin, cout, ks=7, expand=2):
        super().__init__()
        mid = cin * expand
        self.body = nn.Sequential(
            nn.Conv1d(cin, mid, 1, bias=False), nn.BatchNorm1d(mid), nn.SiLU(),
            nn.Conv1d(mid, mid, ks, padding=ks // 2, groups=mid, bias=False), nn.BatchNorm1d(mid), nn.SiLU(),
        )
        self.se = SE(mid)
        self.proj = nn.Sequential(nn.Conv1d(mid, cout, 1, bias=False), nn.BatchNorm1d(cout))
        self.skip = nn.Conv1d(cin, cout, 1, bias=False) if cin != cout else nn.Identity()

    def forward(self, x):
        return self.skip(x) + self.proj(self.se(self.body(x)))


class Net(nn.Module):
    def __init__(self):
        super().__init__()
        # Parallel multi-scale stems for different motif lengths
        self.stem_short = nn.Sequential(nn.Conv1d(4, 28, 5, padding=2, bias=False), nn.BatchNorm1d(28), nn.SiLU())
        self.stem_medium = nn.Sequential(nn.Conv1d(4, 28, 9, padding=4, bias=False), nn.BatchNorm1d(28), nn.SiLU())
        self.stem_long = nn.Sequential(nn.Conv1d(4, 28, 15, padding=7, bias=False), nn.BatchNorm1d(28), nn.SiLU())

        # Hierarchical fusion
        self.fusion = nn.Sequential(nn.Conv1d(84, 80, 1, bias=False), nn.BatchNorm1d(80), nn.SiLU())

        # Inverted residual tower
        widths = [80, 112, 144, 144, 112, 80]
        blocks, c = [], 80
        for i, w in enumerate(widths):
            blocks.append(EffBlock(c, w, ks=7 if i % 2 == 0 else 9, expand=2))
            c = w
            if i in (1, 3):
                blocks.append(nn.MaxPool1d(2))
        self.blocks = nn.Sequential(*blocks)

        self.head = nn.Sequential(nn.Dropout(0.35), nn.Linear(c * 2, 64), nn.SiLU(), nn.Dropout(0.15), nn.Linear(64, 1))

    def forward(self, x):
        h = self.fusion(torch.cat([self.stem_short(x), self.stem_medium(x), self.stem_long(x)], dim=1))
        h = self.blocks(h)
        h = torch.cat([h.mean(-1), h.amax(-1)], dim=1)
        return self.head(h).squeeze(-1)

import torch
import torch.nn as nn
import torch.nn.functional as F


class SE(nn.Module):
    def __init__(self, c, r=4):
        super().__init__()
        h = max(c // r, 4)
        self.fc1 = nn.Linear(c, h)
        self.fc2 = nn.Linear(h, c)

    def forward(self, x):
        s = torch.sigmoid(self.fc2(F.silu(self.fc1(x.mean(-1)))))
        return x * s.unsqueeze(-1)


class SpatialAttn(nn.Module):
    def __init__(self, c):
        super().__init__()
        self.conv = nn.Conv1d(c, 1, 1)

    def forward(self, x):
        return x * torch.sigmoid(self.conv(x))


class GatedBlock(nn.Module):
    def __init__(self, cin, cout, ks=7, expand=2, use_spatial=False):
        super().__init__()
        mid = cin * expand
        self.body = nn.Sequential(
            nn.Conv1d(cin, mid, 1, bias=False), nn.BatchNorm1d(mid), nn.SiLU(),
            nn.Conv1d(mid, mid, ks, padding=ks // 2, groups=mid, bias=False), nn.BatchNorm1d(mid), nn.SiLU(),
        )
        self.se = SE(mid)
        self.spatial = SpatialAttn(mid) if use_spatial else nn.Identity()
        self.proj = nn.Sequential(nn.Conv1d(mid, cout, 1, bias=False), nn.BatchNorm1d(cout))
        self.gate = nn.Sequential(nn.Conv1d(mid, cout, 1, bias=False), nn.Sigmoid())
        self.skip = nn.Conv1d(cin, cout, 1, bias=False) if cin != cout else nn.Identity()

    def forward(self, x):
        h = self.se(self.body(x))
        h = self.spatial(h)
        return self.skip(x) + self.proj(h) * self.gate(h)


class Net(nn.Module):
    def __init__(self):
        super().__init__()
        widths = [68, 100, 132, 132, 100, 68]
        self.stem = nn.Sequential(nn.Conv1d(4, widths[0], 7, padding=3, bias=False), nn.BatchNorm1d(widths[0]), nn.SiLU())

        blocks, c = [], widths[0]
        for i, w in enumerate(widths):
            use_spatial = i in (2, 3)  # spatial attention at middle layers
            blocks.append(GatedBlock(c, w, ks=7 if i % 2 == 0 else 9, expand=2, use_spatial=use_spatial))
            c = w
            if i in (1, 3):
                blocks.append(nn.MaxPool1d(2))
        self.blocks = nn.Sequential(*blocks)

        self.head = nn.Sequential(nn.Dropout(0.32), nn.Linear(c * 2, 64), nn.SiLU(), nn.Dropout(0.12), nn.Linear(64, 1))

    def forward(self, x):
        h = self.blocks(self.stem(x))
        h = torch.cat([h.mean(-1), h.amax(-1)], dim=1)
        return self.head(h).squeeze(-1)

